-- ============================================================
-- NHL95.net TEAM COLORS
-- Run once in Supabase -> SQL Editor. Then edit colors anytime in
-- Table Editor -> team_colors (site picks changes up on next page load).
--   primary_color / secondary_color / accent_color / text_color : team page theme
--   jersey_home / jersey_away : default NOSE jersey palettes for /mod-my-team
--     keys: helmet, jerseyMain, shoulders, stripe1, stripe2, pants,
--           socksMain, socksStripe, gloves, numbers  (hex "#rrggbb")
-- Starting colors were auto-extracted from each team logo - tweak as needed.
-- Original 6 jersey columns are left null so the curated classic jerseys are used
-- (fill them in to override).
-- ============================================================

create table if not exists public.team_colors (
  abbreviation    text primary key,
  team_name       text,
  primary_color   text not null default '#111111',
  secondary_color text not null default '#f59e0b',
  accent_color    text,
  text_color      text,
  jersey_home     jsonb,
  jersey_away     jsonb,
  updated_at      timestamptz not null default now()
);

alter table public.team_colors enable row level security;

drop policy if exists "team_colors public read" on public.team_colors;
create policy "team_colors public read" on public.team_colors for select using (true);

create or replace function public.team_colors_touch() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end $$;
drop trigger if exists team_colors_touch on public.team_colors;
create trigger team_colors_touch before update on public.team_colors
  for each row execute function public.team_colors_touch();

-- Seed (won't overwrite colors you've already edited)
on conflict (abbreviation) do nothing;
